package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	s := string(data)
	i := strings.IndexByte(s, '\n')
	first := s
	rest := ""
	if i >= 0 {
		first = s[:i]
		rest = s[i+1:]
	}
	k, _ := strconv.Atoi(strings.TrimSpace(first))
	counts := map[string]int{}
	start := -1
	b := []byte(rest)
	for j := 0; j <= len(b); j++ {
		alnum := false
		if j < len(b) {
			c := b[j]
			alnum = c >= '0' && c <= '9' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z'
		}
		if alnum {
			if start < 0 {
				start = j
			}
		} else if start >= 0 {
			counts[strings.ToLower(string(b[start:j]))]++
			start = -1
		}
	}
	words := make([]string, 0, len(counts))
	for w := range counts {
		words = append(words, w)
	}
	sort.Slice(words, func(a, c int) bool {
		if counts[words[a]] != counts[words[c]] {
			return counts[words[a]] > counts[words[c]]
		}
		return words[a] < words[c]
	})
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for j := 0; j < len(words) && j < k; j++ {
		fmt.Fprintf(out, "%s %d\n", words[j], counts[words[j]])
	}
}
